static int ocp_write_byte(struct r8152 *tp, u16 type, u16 index, u32 data)
{
	u16 byen = BYTE_EN_BYTE;
	u8 shift = index & 3;
	u32 mask = 0xff;
	__le32 tmp;
	int ret;

	data &= mask;

	if (shift) {
		byen <<= shift;
		data <<= (shift * 8);
		index &= ~3;
	}

	tmp = __cpu_to_le32(data);

	ret = generic_ocp_write(tp, index, byen, sizeof(tmp), &tmp, type);
	WARN_ON_ONCE(ret != sizeof(tmp));

	return ret;
}
